fn factorial_of(n: Int) -> Int {
    let acc: Int = 1;
    loop i in 2..n + 1 {
        acc = acc * i;
    }
    ret acc;
}

fn main() -> Void {
    let n: Int = 10;
    let result: Int = factorial_of(n);
    fx {
        println(n, "! = ", result);
    }
    ret;
}

fn gcd(a: Int, b: Int) -> Int {
    let x: Int = a;
    let y: Int = b;
    loop y != 0 {
        let r: Int = x % y;
        x = y;
        y = r;
    }
    ret x;
}

fn main() -> Void {
    let a: Int = 48;
    let b: Int = 36;
    let g: Int = gcd(a, b);
    fx {
        println("gcd(", a, ", ", b, ") = ", g);
    }
    ret;
}

