fn main() -> Void {
    let limit: Int = 30;
    let composite: Bool[] = [];
    loop i in 0..limit {
        composite = composite + [false];
    }
    loop p in 2..limit {
        if !composite[p] {
            let m: Int = p * p;
            loop m < limit {
                composite[m] = true;
                m = m + p;
            }
        }
    }
    let line: Text = "";
    let first: Bool = true;
    loop i in 2..limit {
        if !composite[i] {
            if !first {
                line = line + ", ";
            }
            line = line + int_to_text(i);
            first = false;
        }
    }
    fx {
        println(line);
    }
    ret;
}

