fn bubbleSort(xs: Int[]) -> Int[] {
    let out: Int[] = xs;
    let n: Int = length(out);
    loop i in 0..n {
        let last: Int = n - 1 - i;
        loop j in 0..last {
            if out[j] > out[j + 1] {
                let tmp: Int = out[j];
                out[j] = out[j + 1];
                out[j + 1] = tmp;
            }
        }
    }
    ret out;
}

