fn binarySearch(xs: Int[], target: Int) -> Int {
    let lo: Int = 0;
    let hi: Int = length(xs) - 1;
    loop lo <= hi {
        let mid: Int = (lo + hi) div 2;
        if xs[mid] == target {
            ret mid;
        }
        if xs[mid] < target {
            lo = mid + 1;
        } else {
            hi = mid - 1;
        }
    }
    ret -1;
}

fn main() -> Void {
    let data: Int[] = [1, 3, 5, 7, 9, 11];
    let idx: Int = binarySearch(data, 7);
    fx {
        println("index = ", idx);
    }
    ret;
}

type Board {
    cols: Int[] = [];
    count: Int = 0;
}

fn safe(b: Board, row: Int, col: Int) -> Bool {
    loop r in 0..row {
        let c: Int = b.cols[r];
        if c == col {
            ret false;
        }
        if abs(c - col) == row - r {
            ret false;
        }
    }
    ret true;
}

fn place(b: Board, row: Int, n: Int) -> Void {
    if row == n {
        b.count = b.count + 1;
        ret;
    }
    loop col in 0..n {
        if safe(b, row, col) {
            b.cols[row] = col;
            place(b, row + 1, n);
        }
    }
    ret;
}

fn main() -> Void {
    let n: Int = 6;
    let b: Board = new Board();
    loop i in 0..n {
        b.cols = b.cols + [0];
    }
    place(b, 0, n);
    fx {
        println("solutions = ", b.count);
    }
    ret;
}

fn minCoins(coins: Int[], amount: Int) -> Int {
    let inf: Int = amount + 1;
    let dp: Int[] = [0];
    loop a in 1..amount + 1 {
        let best: Int = inf;
        loop k in 0..length(coins) {
            let c: Int = coins[k];
            if c <= a {
                best = min(best, dp[a - c] + 1);
            }
        }
        dp = dp + [best];
    }
    if dp[amount] >= inf {
        ret -1;
    }
    ret dp[amount];
}

fn main() -> Void {
    let coins: Int[] = [1, 2, 5];
    let result: Int = minCoins(coins, 11);
    fx {
        println("coins = ", result);
    }
    ret;
}

fn lisLength(xs: Int[]) -> Int {
    let n: Int = length(xs);
    let dp: Int[] = [];
    let best: Int = 0;
    loop i in 0..n {
        let cur: Int = 1;
        loop j in 0..i {
            if xs[j] < xs[i] {
                cur = max(cur, dp[j] + 1);
            }
        }
        dp = dp + [cur];
        best = max(best, cur);
    }
    ret best;
}

fn main() -> Void {
    let data: Int[] = [10, 9, 2, 5, 3, 7, 101, 18];
    let result: Int = lisLength(data);
    fx {
        println("lis = ", result);
    }
    ret;
}

fn lcsLength(a: Text, b: Text) -> Int {
    let n: Int = string_len(a);
    let m: Int = string_len(b);
    let table: Int[][] = [];
    let zeroRow: Int[] = [];
    loop j in 0..m + 1 {
        zeroRow = zeroRow + [0];
    }
    table = table + [zeroRow];
    loop i in 1..n + 1 {
        let row: Int[] = [0];
        loop j in 1..m + 1 {
            let v: Int = 0;
            if a[i - 1] == b[j - 1] {
                v = table[i - 1][j - 1] + 1;
            } else {
                v = max(table[i - 1][j], row[j - 1]);
            }
            row = row + [v];
        }
        table = table + [row];
    }
    ret table[n][m];
}

fn main() -> Void {
    let result: Int = lcsLength("ABCBDAB", "BDCAB");
    fx {
        println("lcs = ", result);
    }
    ret;
}

fn editDistance(a: Text, b: Text) -> Int {
    let n: Int = string_len(a);
    let m: Int = string_len(b);
    let table: Int[][] = [];
    let firstRow: Int[] = [];
    loop j in 0..m + 1 {
        firstRow = firstRow + [j];
    }
    table = table + [firstRow];
    loop i in 1..n + 1 {
        let row: Int[] = [i];
        loop j in 1..m + 1 {
            let cost: Int = 1;
            if a[i - 1] == b[j - 1] {
                cost = 0;
            }
            let del: Int = table[i - 1][j] + 1;
            let ins: Int = row[j - 1] + 1;
            let sub: Int = table[i - 1][j - 1] + cost;
            row = row + [min(min(del, ins), sub)];
        }
        table = table + [row];
    }
    ret table[n][m];
}

fn main() -> Void {
    let result: Int = editDistance("kitten", "sitting");
    fx {
        println("distance = ", result);
    }
    ret;
}

fn merge(left: Int[], right: Int[]) -> Int[] {
    let out: Int[] = [];
    let i: Int = 0;
    let j: Int = 0;
    let nl: Int = length(left);
    let nr: Int = length(right);
    loop i < nl && j < nr {
        if left[i] <= right[j] {
            out = out + [left[i]];
            i = i + 1;
        } else {
            out = out + [right[j]];
            j = j + 1;
        }
    }
    loop i < nl {
        out = out + [left[i]];
        i = i + 1;
    }
    loop j < nr {
        out = out + [right[j]];
        j = j + 1;
    }
    ret out;
}

fn mergeSort(xs: Int[]) -> Int[] {
    let n: Int = length(xs);
    if n <= 1 {
        ret xs;
    }
    let mid: Int = n div 2;
    let left: Int[] = mergeSort(xs[0..mid]);
    let right: Int[] = mergeSort(xs[mid..n]);
    ret merge(left, right);
}

