fn quickSort(xs: Int[]) -> Int[] {
    let n: Int = length(xs);
    if n <= 1 {
        ret xs;
    }
    let pivot: Int = xs[n - 1];
    let less: Int[] = [];
    let equal: Int[] = [];
    let greater: Int[] = [];
    loop i in 0..n {
        let v: Int = xs[i];
        if v < pivot {
            less = less + [v];
        } else if v > pivot {
            greater = greater + [v];
        } else {
            equal = equal + [v];
        }
    }
    let sortedLess: Int[] = quickSort(less);
    let sortedGreater: Int[] = quickSort(greater);
    ret sortedLess + equal + sortedGreater;
}

