fn main() -> Void {
    let adj: Int[][] = [[1, 4], [0, 2, 5], [1, 3], [2, 6], [0, 5], [1, 4, 6], [3, 5]];
    let n: Int = length(adj);
    let visited: Bool[] = [];
    loop i in 0..n {
        visited = visited + [false];
    }
    let queue: Int[] = [0];
    visited[0] = true;
    let head: Int = 0;
    let line: Text = "";
    loop head < length(queue) {
        let u: Int = queue[head];
        head = head + 1;
        if string_len(line) > 0 {
            line = line + " ";
        }
        line = line + int_to_text(u);
        let nbrs: Int[] = adj[u];
        loop k in 0..length(nbrs) {
            let v: Int = nbrs[k];
            if !visited[v] {
                visited[v] = true;
                queue = queue + [v];
            }
        }
    }
    fx {
        println(line);
    }
    ret;
}

fn main() -> Void {
    let n: Int = 5;
    let eu: Int[] = [0, 0, 1, 1, 2, 3];
    let ev: Int[] = [1, 2, 2, 3, 3, 4];
    let ew: Int[] = [4, 1, 2, 1, 5, 3];
    let inf: Int = 1000000;
    let dist: Int[] = [];
    let done: Bool[] = [];
    loop i in 0..n {
        dist = dist + [inf];
        done = done + [false];
    }
    dist[0] = 0;
    loop round in 0..n {
        let u: Int = -1;
        loop i in 0..n {
            if !done[i] && dist[i] < inf {
                if u < 0 || dist[i] < dist[u] {
                    u = i;
                }
            }
        }
        if u < 0 {
            break;
        }
        done[u] = true;
        loop e in 0..length(eu) {
            let other: Int = -1;
            if eu[e] == u {
                other = ev[e];
            } else if ev[e] == u {
                other = eu[e];
            }
            if other >= 0 {
                let cand: Int = dist[u] + ew[e];
                if cand < dist[other] {
                    dist[other] = cand;
                }
            }
        }
    }
    fx {
        println("distance = ", dist[4]);
    }
    ret;
}

fn naiveFind(text: Text, pattern: Text) -> Int {
    let n: Int = string_len(text);
    let m: Int = string_len(pattern);
    let last: Int = n - m + 1;
    loop i in 0..last {
        let matched: Bool = true;
        let j: Int = 0;
        loop j < m && matched {
            if text[i + j] != pattern[j] {
                matched = false;
            }
            j = j + 1;
        }
        if matched {
            ret i;
        }
    }
    ret -1;
}

fn main() -> Void {
    let idx: Int = naiveFind("mississippi", "sip");
    fx {
        println("index = ", idx);
    }
    ret;
}
